//
// Alignment with bwa aln and sort
//

include { BWA_ALN        } from 'nf-core/bwa/aln'
include { BWA_SAMSE      } from 'nf-core/bwa/samse'
include { BWA_SAMPE      } from 'nf-core/bwa/sampe'
include { SAMTOOLS_INDEX } from 'nf-core/samtools/index'

workflow FASTQ_ALIGN_BWAALN {
    take:
    ch_reads // channel (mandatory): [ val(meta), path(reads) ]. subworkImportant: meta REQUIRES single_end` entry!
    ch_index // channel (mandatory): [ val(meta), path(index) ]

    main:

    // WARNING: You must specify in your prefix `meta.id_index` in your `modules.conf`
    // to ensure that you do not overwrite multiple BAM files from one sample mapped
    // against multiple references. This meta map is added by the subworkflow but can be removed
    // after if necessary.

    // Ensure when multiple references are provide, that reference/read combinations
    // are correctly associated throughout the subworkflow by copying the sample
    // specific metadata to the index on each combination

    ch_prepped_input = ch_reads
        .combine(ch_index)
        .map { meta, reads, meta_index, index ->

            // Create a combined id that includes the ids of the reads and the index used.
            // Also keep the id of the index with a new name to avoid name collisions.
            def key_read_ref = meta.id + "_" + meta_index.id
            def id_index = meta_index.id

            [meta + [key_read_ref: key_read_ref] + [id_index: id_index], reads, meta_index + [key_read_ref: key_read_ref] + [id_index: id_index], index]
        }

    // Drop the index_meta, as the id of the index is now kept within the read meta.
    ch_preppedinput_for_bwaaln = ch_prepped_input.multiMap { meta, reads, _meta_index, index ->
        reads: [meta, reads]
        index: [meta, index]
    }

    // Set as independent channel to allow repeated joining but _with_ sample specific metadata
    // to ensure right reference goes with right sample
    ch_reads_newid = ch_prepped_input.map { meta, reads, _meta_index, _index -> [meta, reads] }
    ch_index_newid = ch_prepped_input.map { meta, _reads, _meta_index, index -> [meta, index] }

    // Alignment and conversion to bam
    BWA_ALN(ch_preppedinput_for_bwaaln.reads, ch_preppedinput_for_bwaaln.index)

    ch_sai_for_bam = ch_reads_newid
        .join(BWA_ALN.out.sai)
        .join(ch_index_newid)
        .branch { meta, _reads, _sai, _index ->
            pe: !meta.single_end
            se: meta.single_end
        }

    // Split as PE/SE have different SAI -> BAM commands
    ch_sai_for_bam_pe = ch_sai_for_bam.pe.multiMap { meta, reads, sai, index ->
        reads: [meta, reads, sai]
        index: [meta, index]
    }

    ch_sai_for_bam_se = ch_sai_for_bam.se.multiMap { meta, reads, sai, index ->
        reads: [meta, reads, sai]
        index: [meta, index]
    }

    BWA_SAMPE(ch_sai_for_bam_pe.reads, ch_sai_for_bam_pe.index)

    BWA_SAMSE(ch_sai_for_bam_se.reads, ch_sai_for_bam_se.index)

    ch_bam_for_index = BWA_SAMPE.out.bam.mix(BWA_SAMSE.out.bam)

    // Index all
    SAMTOOLS_INDEX(ch_bam_for_index)

    // Remove superfluous internal maps to minimise clutter as much as possible
    ch_bam_for_emit = ch_bam_for_index.map { meta, bam -> [meta - meta.subMap('key_read_ref'), bam] }
    ch_index_for_emit = SAMTOOLS_INDEX.out.index.map { meta, index -> [meta - meta.subMap('key_read_ref'), index] }

    emit:
    bam   = ch_bam_for_emit // channel: [ val(meta), path(bam) ]
    index = ch_index_for_emit // channel: [ val(meta), path(index) ]
}

// IMPORTANT: Add this configuration to your modules.config
// These settings are to ensure you include the reference information within the output file names, to prevent overwriting!
// `meta.id_index` is created and used within the workflow. You must reuse this meta field if you wish to customise the file naming scheme.

process {

    publishDir = { "${params.outdir}/${task.process.tokenize(':')[-1].tokenize('_')[0].toLowerCase()}" }

    withName: '.*FASTQ_ALIGN_BWAALN:BWA_ALN' {
        ext.prefix = { "${meta.id}_${meta.id_index}" }
    }

    withName: '.*FASTQ_ALIGN_BWAALN:BWA_SAMSE' {
        ext.prefix = { "${meta.id}_${meta.id_index}" }
    }

    withName: '.*FASTQ_ALIGN_BWAALN:BWA_SAMPE' {
        ext.prefix = { "${meta.id}_${meta.id_index}" }
    }

    withName: '.*FASTQ_ALIGN_BWAALN:SAMTOOLS_INDEX' {
        ext.prefix = { "${meta.id}_${meta.id_index}" }
    }
}

nextflow_workflow {

    name "Test Workflow FASTQ_ALIGN_BWAALN"
    config "./nextflow.config"
    script "../main.nf"
    workflow "FASTQ_ALIGN_BWAALN"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/fastq_align_bwaaln"
    tag "fastq_align_bwaaln"

    tag "bwa"
    tag "bwa/index"
    tag "bwa/aln"
    tag "bwa/samse"
    tag "bwa/sampe"
    tag "samtools"
    tag "samtools/index"

    test("test_fastq_align_bwaaln_singleend") {
        setup {
            run("BWA_INDEX") {
                script "../../../../modules/nf-core/bwa/index/main.nf"
                process {
                    """
                    input[0] = [
                        [id:'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true)
                    ]
                    input[1] = []
                    """
                }
            }
        }
        when {

            workflow {
                """
                input[0] = Channel.of([
                    [id:'test', single_end:true],
                    [file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)]
                ])
                input[1] = BWA_INDEX.out.index
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    file(workflow.out.index[0][1]).name
                    ).match() }
            )
        }
    }
    test("test_fastq_align_bwaaln_paired_end") {
        setup {
            run("BWA_INDEX") {
                script "../../../../modules/nf-core/bwa/index/main.nf"
                process {
                    """
                    input[0] = [
                        [id:'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true)
                    ]
                    input[1] = []
                    """
                }
            }
        }
        when {

            workflow {
                """
                input[0] = Channel.of([
                    [id:'test', single_end:false],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists:true)
                    ]
                ])
                input[1] = BWA_INDEX.out.index
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    file(workflow.out.index[0][1]).name
                    ).match() }
            )
        }
    }
    test("test_fastq_align_bwaaln_both") {

        setup {
            run("BWA_INDEX") {
                script "../../../../modules/nf-core/bwa/index/main.nf"

                process {
                    """
                    input[0] = [
                        [id:'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true)
                    ]
                    input[1] = []
                    """
                }
            }
        }
        when {

            workflow {
                """
                input[0] = Channel.fromList([
                    [
                        [id:'test', single_end:false],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists:true)
                        ]
                    ],
                    [
                        [id:'test2', single_end:true],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)
                        ]
                    ]
                ])
                input[1] = BWA_INDEX.out.index
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    file(workflow.out.index[0][1]).name
                    ).match() }
            )
        }
    }
    test("test_fastq_align_bwa_multiref") {

        setup {
            run("BWA_INDEX") {
                script "../../../../modules/nf-core/bwa/index/main.nf"
                process {
                    """
                    input[0] = Channel.fromList([
                        [
                            [id:'reftest'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true)
                        ],
                        [
                            [id:'reftest2'],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists:true)
                        ]
                    ])
                    input[1] = []
                    """
                }
            }
        }
        when {

            workflow {
                """
                input[0] = Channel.fromList([
                    [
                        [id:'test', single_end:false],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists:true)
                        ]
                    ],
                    [
                        [id:'test2', single_end:true],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)
                        ]
                    ]
                ])
                input[1] = BWA_INDEX.out.index
                """
            }
        }
        then {
            assert workflow.success
            assertAll(
                { assert snapshot(
                    bam(workflow.out.bam[0][1]).getReadsMD5(),
                    file(workflow.out.index[0][1]).name
                    ).match() }
            )
        }
    }
    test("test_fastq_align_bwa_multiref -- stub") {
        tag "stub"
        options '-stub'
        setup {
            run("BWA_INDEX") {
                script "../../../../modules/nf-core/bwa/index/main.nf"
                process {
                    """
                    input[0] = Channel.fromList([
                        [
                            [id:'reftest'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists:true)
                        ],
                        [
                            [id:'reftest2'],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists:true)
                        ]
                    ])
                    input[1] = []
                    """
                }
            }
        }
        when {

            workflow {
                """
                input[0] = Channel.fromList([
                    [
                        [id:'test', single_end:false],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists:true)
                        ]
                    ],
                    [
                        [id:'test2', single_end:true],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists:true)
                        ]
                    ]
                ])
                input[1] = BWA_INDEX.out.index
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out
                ).match() }
            )
        }
    }
}

